KG42.register("rules-514737d4ca1785479a78a4ff",{"id":"39-dynamic_congestion_tariff::v141-c-R001","paper":"39-dynamic_congestion_tariff","record":{"rule_id":"v141-c-R001","mechanism_id":"v141-a-M02","name":"Demand submission","process_stage":"bidding","market_meaning":"DPT price signals guide aggregators' updates of the demand quantities represented by their tentative purchasing plans, whose results are returned to the DSO as demand responses. Scope: Aggregator tentative purchasing-plan and demand-response updates during iterative DPT congestion-management planning. Condition: Within the iterative process, using the DPT signals received for the current planning update. Each aggregator's tentative purchasing quantities are planned to minimize energy cost plus network tariff cost, subject to EV operating limits, household thermal limits and HP input-power limits. Scope: Per-aggregator tentative purchasing-plan updates for the studied EV and HP flexible demands. Condition: During the DPT iterative planning process.","independence_rationale":"Relations governed by the approved function bidding.demand under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["bidding.demand","coordination.price_signal"],"E":[{"edge_id":"v141-c-R001-E001","source":"coordination.price_signal","target":"bidding.demand","type":"links","constraint_ids":["v141-c-R001-C001"],"evidence_ids":["v141-b-g02-e015","v141-b-g13-E13"]}],"omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"bidding","context_text":"Aggregator tentative purchasing-plan and demand-response updates during iterative DPT congestion-management planning. | Per-aggregator tentative purchasing-plan updates for the studied EV and HP flexible demands.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g02-e004","v141-b-g02-e015","v141-b-g13-E13","v141-b-g19-E19"]},"x":[{"variable_id":"x-p-it","symbol":"p_{i,t}","meaning":"Charging power of EVs of aggregator i at planning period t; one component of the aggregator's tentative purchasing-plan quantities and of the demand response submitted through (6).","kind":"operational","domain":"Real-valued EV charging power schedule over i in N_B and t in N_t; the source optimization bounds it by (3).","unit":null,"indices":["i in N_B","t in N_t"],"evidence_ids":["v141-b-g04-E04","v141-b-g02-e006","v141-b-g20-E20"]},{"variable_id":"x-phat-it","symbol":"\\hat p_{i,t}","meaning":"Power consumption of HPs of aggregator i at planning period t; one component of the aggregator's tentative purchasing-plan quantities and of the demand response submitted through (6).","kind":"operational","domain":"Real-valued HP power-consumption schedule over i in N_B and t in N_t; the source optimization bounds it by (5).","unit":null,"indices":["i in N_B","t in N_t"],"evidence_ids":["v141-b-g04-E04","v141-b-g02-e006","v141-b-g20-E20"]},{"variable_id":"x-pa-it","symbol":"p_{i,t}^a","meaning":"Aggregated demand response formed by aggregator i and sent to the DSO, defined in (6) as the load-bus mapping of the aggregator's total EV charging plus HP power consumption.","kind":"operational","domain":"Real-valued aggregated demand response at load buses over i in N_B and t in N_t, determined by (6).","unit":null,"indices":["i in N_B","t in N_t"],"evidence_ids":["v141-b-g02-e006","v141-b-g20-E20"]}],"theta":[{"parameter_id":"theta-Ei","symbol":"E_i","meaning":"Customer-to-load-bus mapping matrix used in (6) to map aggregator EV and HP power into load-bus demand response.","value":{"kind":"symbolic","number_value":null,"text_value":"customer-to-load-bus mapping matrix"},"unit":null,"indices":["i in N_B"],"evidence_ids":["v141-b-g02-E02","v141-b-g20-E20"]}],"phi":[{"constraint_id":"v141-c-R001-C001","kind":"procedural","role":"core","statement":"DPT price signals guide aggregators' updates of the demand quantities represented by their tentative purchasing plans, whose results are returned to the DSO as demand responses. Scope: Aggregator tentative purchasing-plan and demand-response updates during iterative DPT congestion-management planning. Condition: Within the iterative process, using the DPT signals received for the current planning update.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["coordination.price_signal","bidding.demand"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g02-e015","v141-b-g13-E13"]},{"constraint_id":"v141-c-R001-C002","kind":"procedural","role":"core","statement":"Each aggregator's tentative purchasing quantities are planned to minimize energy cost plus network tariff cost, subject to EV operating limits, household thermal limits and HP input-power limits. Scope: Per-aggregator tentative purchasing-plan updates for the studied EV and HP flexible demands. Condition: During the DPT iterative planning process.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["bidding.demand"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g02-e004","v141-b-g13-E13","v141-b-g19-E19"]},{"constraint_id":"v141-c-R001-C003","kind":"mathematical","role":"core","statement":"After solving its optimal planning problem, aggregator i forms the aggregated demand response sent to the DSO as the load-bus mapping of its total EV charging and HP power consumption: p_{i,t}^a = E_i(p_{i,t}+\\hat p_{i,t}) for all t in N_t.","expression":"p_{i,t}^a = E_i(p_{i,t}+\\hat p_{i,t}),\\quad \\forall t\\in N_t \\tag{6}","formalization_origin":"source","template_id":null,"members":["bidding.demand"],"variable_refs":["x-p-it","x-phat-it","x-pa-it"],"parameter_refs":["theta-Ei"],"evidence_ids":["v141-b-g02-e006","v141-b-g20-E20"]}],"pi":[{"evidence_id":"v141-b-g02-e004","location":{"location_id":"src-c263a83472-p04-c2r1__v141-a-M02-clearing","page":4,"printed_page":null,"section":"III-A.1) Formulation at the Aggregator Side","anchor_text":"NETWORKS 2151 concept. The optimal planning problem for aggregator i is formulated as (1)-(5). min p","equation_id":"(1)-(3)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"An aggregator can use a quadratic function to represent the total cost including energy consumption and network tariff as shown in (1). The quadratic term in (1) is due to the DPT received from the DSO (R_t is the DPT; therefore, it is a fixed parameter for the optimizations at the aggregator side). The optimal planning problem for aggregator i is formulated as (1)-(5). \\min_{p_{i,t},\\hat p_{i,t}} \\sum_{t\\in N_T}(p_{i,t}+\\hat p_{i,t})^T E_i^T R_t E_i(p_{i,t}+\\hat p_{i,t}) + \\sum_{t\\in N_T}(c_t^1)^T(p_{i,t}+\\hat p_{i,t}) \\quad (1)"},{"evidence_id":"v141-b-g02-e015","location":{"location_id":"src-c263a83472-p05-c1r4__v141-a-M02-coordination","page":5,"printed_page":null,"section":"III-B. Control Diagram of the Iteration Process","anchor_text":"g g p only be employed to calculate DT rates, but not the DPT rates. pa In Section III-B, the margin","equation_id":null,"figure_id":"Fig. 3","table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"definition"},"source_text":"From the DSO point of view, the price-based congestion management process is an indirect control process. The aggregators respond to the price signals from the DSO (e.g., DT or DPT), and the DSO can adjust the price signals such that the responses from the aggregators can respect the network limits. The control framework of the whole congestion management process is shown in Fig. 3. The target system comprises of the distribution network and two actors, i.e., the DSO and aggregators. The aggregators receive the DPTs and make their own optimal planning (DR). Then, the planning results are sent to the DSO."},{"evidence_id":"v141-b-g13-E13","location":{"location_id":"src-c263a83472-p03-c2r4__v141-a-M02-coordination","page":3,"printed_page":null,"section":"II-B. Congestion Management Through Power Tariff","anchor_text":"ers of implementing the DPT method for congestion manage- der ment is illustrated in Fig. 2. Step 1,","equation_id":null,"figure_id":"Fig. 2","table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"Step 1, the DSO initiates the iterative process by sending out tentative DPTs (= 0). Step 2, the aggregators will separately make their own optimal purchasing plans by minimizing the energy cost and the network tariff cost. Step 3, the aggregators will send back the tentative demand responses (DRs) to the DSO. Step 4, with the new information, the DSO will be able to identify the congestion points (if any) and modify the DPT rates according to the identified congestion. Step 5, the DSO sends out the new DPTs to the aggregator and the iterative process continues (go back to Step 2) till the network constraints are satisfied and the final DPT rates are determined. As in many other congestion management methods, Step 4 is to identify the congestion risk and allocate the risk to the responsible party through the DPT calculation (the DPT is also a locational price). Step 2 is to optimize the energy consumption plan by each aggregator taking into account the congestion risk reflected in the DPT. Steps 2∼5 form an iterative process to finally reach an optimal planning with respect to the network constraints."},{"evidence_id":"v141-b-g19-E19","location":{"location_id":"src-c263a83472-p04-c2r2__v141-a-M02-clearing","page":4,"printed_page":null,"section":"III-A.1) Formulation at the Aggregator Side","anchor_text":"t_≤t (2) pmini,t ≤pi,t ≤pmaxi,t ∀t ∈NT, (3) a- Ka,mini,t ≤ Ai,t,t_ˆpi,t_ + ui,t ≤Ka,maxi,t , ∀t ∈NT,","equation_id":"(2)-(6)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"Constraints (2) - (3) are from the limits of EVs. Constraint (4) represents the thermal limits of households and (5) gives the input power limits of HPs. Constraint (4) is derived from the thermal process analysis of the household and the HP as shown in [4]."},{"evidence_id":"v141-b-g02-E02","location":{"location_id":"src-c263a83472-p01-c1r3__v141-a-M02-clearing","page":1,"printed_page":null,"section":"Nomenclature","anchor_text":"( ), e ect c ve c e ( V), eat pu p ( ). Va NOMENCLATURE Parameters Ai,t,t_ coefﬁcient matrix, descri","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-01.png","occurrence_role":"definition"},"source_text":"Parameters: \\(A_{i,t,t'}\\) coefficient matrix, describe the relations between the power consumption and temperature change of the household; \\(D\\) power transfer distribution factor (PTDF); \\(\\tilde E_{i,t}, E_i\\) customer to load bus mapping matrix; \\(F_t\\) line loading limit of active power; \\(K_{i,t}^{a,min}\\) lower temperature limit; \\(K_{i,t}^{a,max}\\) upper temperature limit; \\(N_B\\) set of aggregators; \\(N_T\\) set of planning periods; \\(N_L\\) set of lines; \\(N_d\\) set of demand bus; \\(\\underline V\\) voltage lower limit."},{"evidence_id":"v141-b-g02-e006","location":{"location_id":"src-c263a83472-p04-c2r2__v141-a-M02-clearing","page":4,"printed_page":null,"section":"III-A.1) Formulation at the Aggregator Side","anchor_text":"t_≤t (2) pmini,t ≤pi,t ≤pmaxi,t ∀t ∈NT, (3) a- Ka,mini,t ≤ Ai,t,t_ˆpi,t_ + ui,t ≤Ka,maxi,t , ∀t ∈NT,","equation_id":"(2)-(6)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"After solving the optimal problem, the aggregator i will have a tentative optimal plan (p^*_{i,t}, \\hat p^*_{i,t}). Then (6) can be used to formulate the aggregated DR for aggregator i, which will be sent to the DSO.\np_{i,t}^a = E_i(p_{i,t}+\\hat p_{i,t}), \\forall t\\in N_t \\quad (6)"},{"evidence_id":"v141-b-g04-E04","location":{"location_id":"src-c263a83472-p01-c2r3__v141-a-M02-pricing","page":1,"printed_page":null,"section":"Nomenclature","anchor_text":"Variables pev, php, pc power level of EV, HP and conventional loads of a household/customer en pi, p","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-01.png","occurrence_role":"definition"},"source_text":"Variables: \\(p^{ev}, p^{hp}, p^c\\) power level of EV, HP and conventional loads of a household/customer; \\(p_i, p_{i,t}\\) charging power of EVs of one aggregator; \\(\\hat p_i, \\hat p_{i,t}\\) power consumption of HPs of one aggregator; \\(r, r_t\\) energy-based regulation price, i.e., DT rates; \\(r^p, r_t^p\\) power-based regulation price, i.e., DPT rates; \\(R\\) matrix form of the DPT rates; \\(s_t\\) total apparent power at each load point; \\(\\lambda_t\\) Lagrange multiplier (LM) of line limit constraint; \\(\\rho_t\\) LM of load equation; \\(\\omega_t\\) LM of voltage constraint."},{"evidence_id":"v141-b-g20-E20","location":{"location_id":"src-c263a83472-p04-c2r3__v141-a-M02-clearing","page":4,"printed_page":null,"section":"III-A.2) Formulation at the DSO Side","anchor_text":"ent pai,t = Ei pi,t + ˆpi,t , ∀t ∈Nt (6) he 2) Formulation at the DSO Side: At the DSO side, there i","equation_id":"(6)-(10)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"After solving the optimal problem, the aggregator \\(i\\) will have a tentative optimal plan \\((p_{i,t}^*,\\hat p_{i,t}^*)\\). Then (6) can be used to formulate the aggregated DR for aggregator \\(i\\), which will be sent to the DSO. \\[p_{i,t}^a=E_i(p_{i,t}+\\hat p_{i,t}),\\quad \\forall t\\in N_t \\tag{6}\\]"}],"field_notes":{"empty_E_reason":null,"empty_x_reason":null,"empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M02-clearing","v141-a-M02-coordination","v141-a-M02-participation","v141-a-M02-pricing"],"extras":{"decision_anchor":"bidding.demand","graph_fact_supports":[[{"evidence_id":"v141-b-g02-e015","quote":"The aggregators receive the DPTs and make their own optimal planning (DR). Then, the planning results are sent to the DSO."},{"evidence_id":"v141-b-g13-E13","quote":"Step 2, the aggregators will separately make their own optimal purchasing plans by minimizing the energy cost and the network tariff cost. Step 3, the aggregators will send back the tentative demand responses (DRs) to the DSO."}],[{"evidence_id":"v141-b-g13-E13","quote":"Step 2, the aggregators will separately make their own optimal purchasing plans by minimizing the energy cost and the network tariff cost."},{"evidence_id":"v141-b-g02-e004","quote":"The optimal planning problem for aggregator i is formulated as (1)-(5)."},{"evidence_id":"v141-b-g19-E19","quote":"Constraints (2) - (3) are from the limits of EVs. Constraint (4) represents the thermal limits of households and (5) gives the input power limits of HPs."}]],"C2_formalization":{"graph_sha256":"4a1b4191c236267d4464fc7eaef50ecd484b20a17b33f895de98576d1b020778","applicability":"formalized","reason":"Source eq. (6) gives an explicit demand-response submission formula, so the rule is not purely non-mathematical. I formalize that equation as C003. The broader aggregator optimization (1)-(5) remains not_formalized in C002 because candidate B evidence has unresolved transcription ambiguities (c_t^1 vs c_t 1; N_t vs N_T) and the frozen C.1 draft lacks typed variable/parameter nodes; those are requested for revision. All cited B evidence is unreviewed candidate support, not independently verified.","bindings":[{"object_id":"v141-c-R001-C001","node_ids":["coordination.price_signal","bidding.demand"],"edge_ids":["v141-c-R001-E001"],"rationale":"C001 states that DPT price signals guide aggregators' demand-quantity updates and that the results are returned to the DSO; the frozen edge E001 links coordination.price_signal to bidding.demand."},{"object_id":"v141-c-R001-C002","node_ids":["bidding.demand","coordination.price_signal"],"edge_ids":["v141-c-R001-E001"],"rationale":"C002 describes the per-aggregator tentative purchasing-plan optimization minimizing energy cost plus network-tariff cost under DPT; the decision object is bidding.demand and the DPT network-tariff signal is coordination.price_signal, linked by E001. The optimization itself is left not_formalized because of unresolved transcription ambiguity."},{"object_id":"v141-c-R001-C003","node_ids":["bidding.demand"],"edge_ids":[],"rationale":"Equation (6) defines the aggregated demand response p_{i,t}^a submitted by aggregator i to the DSO as a mapping of its EV and HP power schedules; this is the mathematical content of the demand-submission step at bidding.demand."},{"object_id":"x-p-it","node_ids":["bidding.demand"],"edge_ids":["v141-c-R001-E001"],"rationale":"The EV charging decision is one component of the demand quantity at bidding.demand; the DPT signal in coordination.price_signal influences this decision through the optimization represented by E001, and the resulting schedule enters the submitted demand in (6)."},{"object_id":"x-phat-it","node_ids":["bidding.demand"],"edge_ids":["v141-c-R001-E001"],"rationale":"The HP power decision is one component of the demand quantity at bidding.demand; the DPT signal in coordination.price_signal influences this decision through the optimization represented by E001, and the resulting schedule enters the submitted demand in (6)."},{"object_id":"x-pa-it","node_ids":["bidding.demand"],"edge_ids":[],"rationale":"p_{i,t}^a is the aggregated demand response submitted to the DSO as defined by (6); it is the direct operational object of bidding.demand. Equation (6) itself does not use the DPT price signal, so no edge is attached."},{"object_id":"theta-Ei","node_ids":["bidding.demand"],"edge_ids":[],"rationale":"E_i is the mapping matrix used in (6) to convert aggregator EV plus HP power into load-bus demand, so it parameterizes the bidding.demand submission."}],"revision_requests":["Confirm whether this rule should formalize the full aggregator optimization (1)-(5) or only the demand-response hand-off (6). If the full optimization is in scope, add or confirm typed variable and parameter objects for p_{i,t}, \\hat p_{i,t}, R_t, c_t, E_i, A_{i,t,t'}, d_{i,t}, e_i^{min}, e_i^{max}, e_{i,0}, p_{i,t}^{min}, p_{i,t}^{max}, K_{i,t}^{a,min}, K_{i,t}^{a,max}, u_{i,t}, \\hat p_{i,t}^{min}, and \\hat p_{i,t}^{max}, and bind them to bidding.demand, coordination.price_signal, and edge v141-c-R001-E001 as appropriate.","Resolve the source transcription of the energy-cost term in (1): candidate evidence v141-b-g02-e004 prints (c_t^1)^T while candidate evidence v141-b-g17-E17 prints (c_t\\mathbf{1})^T; this must be fixed before formalizing the objective.","Resolve N_t versus N_T in (2) and (6) versus (3)-(5); C003 transcribes (6) with N_t exactly as printed, but the relationship to N_T is unresolved.","Confirm whether p_{i,t}^a is an independent submitted variable or only an output defined by (6); current formalization treats it as an operational demand-response variable defined by (6)."]}},"quarantined_references":[]}});
